function default_db(): array { return ['users'=>[], 'posts'=>[], 'favorites'=>[], 'conversations'=>[], 'messages'=>[], 'reports'=>[], 'saved_searches'=>[], 'notifications'=>[], 'payments'=>[]]; }
function db_read(): array {
    global $dataFile;
    if (!is_file($dataFile)) return default_db();
    $raw = @file_get_contents($dataFile);
    $db = json_decode($raw ?: '', true);
    return is_array($db) ? array_replace(default_db(), $db) : default_db();
}
function db_write(callable $mutator): mixed {
    global $dataFile;
    $fh = @fopen($dataFile, 'c+');
    if (!$fh) throw new RuntimeException('امکان دسترسی به فضای ذخیره‌سازی وجود ندارد.');
    flock($fh, LOCK_EX); rewind($fh);
    $db = json_decode(stream_get_contents($fh) ?: '', true);
    if (!is_array($db)) $db = default_db();
    $db = array_replace(default_db(), $db);
    $result = $mutator($db);
    rewind($fh); ftruncate($fh, 0);
    fwrite($fh, json_encode($db, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRETTY_PRINT));
    fflush($fh); flock($fh, LOCK_UN); fclose($fh);
    return $result;
}
function e(mixed $v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function uid(string $p): string { return $p.'_'.bin2hex(random_bytes(6)); }
function now(): string { return date('c'); }
function redirect(string $url): never { header('Location: '.$url); exit; }
function flash(string $message, string $type='ok'): void { $_SESSION['flash']=[$message,$type]; }
function csrf(): string { if(empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(24)); return $_SESSION['csrf']; }
function verify_csrf(): void { if(!hash_equals($_SESSION['csrf']??'', $_POST['csrf']??'')) throw new RuntimeException('درخواست نامعتبر است. صفحه را تازه‌سازی کنید.'); }
function current_user(array $db): ?array { $id=$_SESSION['uid']??null; if(!$id)return null; foreach($db['users'] as $u)if(($u['id']??'')===$id)return $u; return null; }
function require_user(array $db): array { $u=current_user($db); if(!$u){flash('برای ادامه وارد حساب شوید.','warn');redirect(APP_PATH.'?page=login');} return $u; }
function normalize_phone(string $p): string { $p=preg_replace('/\D+/','',$p)??''; if(str_starts_with($p,'98')&&strlen($p)===12)$p='0'.substr($p,2); if(str_starts_with($p,'9')&&strlen($p)===10)$p='0'.$p; return $p; }
function money(mixed $n): string { $n=(int)$n; return $n>0?number_format($n).' تومان':'توافقی'; }
function upload_images(): array {
    global $uploadDir;
    if(empty($_FILES['images'])||!is_array($_FILES['images']['name']))return [];
    $out=[];$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];$count=min(count($_FILES['images']['name']),MAX_IMAGES);
    for($i=0;$i<$count;$i++){
        if(($_FILES['images']['error'][$i]??1)!==UPLOAD_ERR_OK)continue;
        $tmp=$_FILES['images']['tmp_name'][$i];$size=(int)($_FILES['images']['size'][$i]??0);if($size<=0||$size>MAX_IMAGE_BYTES)continue;
        $mime=(new finfo(FILEINFO_MIME_TYPE))->file($tmp);if(!isset($allowed[$mime]))continue;
        $name=date('YmdHis').'-'.bin2hex(random_bytes(5)).'.'.$allowed[$mime];if(move_uploaded_file($tmp,$uploadDir.'/'.$name))$out[]=$name;
    } return $out;
}
function post_image(array $p): string {
    if(!empty($p['demo_image'])) return $p['demo_image'];
    if(!empty($p['images'][0])) return '/marketplace-uploads/'.rawurlencode(basename($p['images'][0]));
    return 'data:image/svg+xml;base64,'.base64_encode('<svg xmlns="http://www.w3.org/2000/svg" width="800" height="600"><rect width="100%" height="100%" fill="#f1f3f5"/><circle cx="400" cy="250" r="72" fill="#e1e5e9"/><rect x="250" y="350" width="300" height="28" rx="14" fill="#e1e5e9"/></svg>');
}
