<?php if(!$conv):?><div class="empty">گفتگو پیدا نشد.</div><?php else:$msgs=array_values(array_filter($db['messages'],fn($m)=>$m['conversation_id']===$cid));?><main class="chat-page"><div class="messages" id="messages"><?php foreach($msgs as $m):?><div class="msg <?=$m['sender_id']===$u['id']?'me':''?>"><?=nl2br(e($m['text']))?><div class="subtle"><?=e(date('H:i',strtotime($m['created_at'])))?></div></div><?php endforeach?></div><form method="post" class="compose"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="send_message"><input type="hidden" name="conversation_id" value="<?=e($cid)?>"><input name="text" maxlength="1200" required placeholder="پیام بنویس..."><button class="btn primary">ارسال</button></form></main><script>const m=document.getElementById('messages');m.scrollTop=m.scrollHeight</script><?php endif?>

<?php else:?>
<main class="main"><div class="install-hint"><span style="font-size:20px">▣</span><span><b>مثل اپ استفاده کن</b><br>از منوی مرورگر «افزودن به صفحه اصلی» را بزن.</span></div><nav class="category-strip"><a class="cat-chip <?=$filterCat===''?'active':''?>" href="<?=APP_PATH?><?=($filterCity?'?city='.urlencode($filterCity):'')?>"><span class="cat-icon">⌕</span><span>همه</span></a><?php foreach($categories as $cat=>$subs):?><a class="cat-chip <?=$filterCat===$cat?'active':''?>" href="<?=APP_PATH?>?category=<?=urlencode($cat)?><?=$filterCity?'&city='.urlencode($filterCity):''?>"><span class="cat-icon"><?=e($categoryIcons[$cat]??'•')?></span><span><?=e($cat)?></span></a><?php endforeach?></nav><div class="section-head"><div><h1><?=($q||$filterCat||$filterCity)?'نتایج':'تازه‌ترین آگهی‌ها'?></h1><p><?=e($filterCity?:'همه شهرها')?> · <?=number_format(count($visiblePosts))?> آگهی</p></div></div><div class="content-grid"><aside class="filter-card"><h3>فیلتر آگهی‌ها</h3><form method="get"><div class="field"><label>شهر</label><select name="city"><option value="">همه شهرها</option><?php foreach($cities as $c):?><option value="<?=e($c)?>" <?=$filterCity===$c?'selected':''?>><?=e($c)?></option><?php endforeach?></select></div><div class="field"><label>دسته‌بندی</label><select name="category"><option value="">همه دسته‌ها</option><?php foreach($categories as $cat=>$subs):?><option value="<?=e($cat)?>" <?=$filterCat===$cat?'selected':''?>><?=e($cat)?></option><?php endforeach?></select></div><div class="field"><label>جست‌وجو</label><input name="q" value="<?=e($q)?>" placeholder="مثلاً آیفون"></div><button class="btn" style="width:100%">اعمال فیلتر</button></form></aside><section><div class="listings"><?php foreach($visiblePosts as $p):?><a class="listing" href="<?=APP_PATH?>?id=<?=e($p['id'])?>"><div class="listing-media"><img src="<?=e(post_image($p))?>" loading="lazy" alt="<?=e($p['title'])?>"><span class="fav-dot">♡</span><?php if($p['demo']??false):?><span class="demo-badge">نمایشی</span><?php endif?><?php if(!empty($p['featured'])):?><span class="feature-badge">پیشنهاد ویژه</span><?php endif?></div><div class="listing-body"><div class="listing-title"><?=e($p['title'])?></div><div class="listing-price"><?=e(money($p['price']??0))?></div><div class="listing-meta"><span><?=e($p['city'])?><?=!empty($p['district'])?'، '.e($p['district']):''?></span><span><?=e(ago($p['created_at']))?></span></div></div></a><?php endforeach?></div><?php if(!$visiblePosts):?><div class="empty">چیزی پیدا نشد.<br><br><a class="btn primary" href="<?=APP_PATH?>?page=new">ثبت آگهی</a></div><?php endif?></section></div></main>
<?php endif?>

